class TestSignup():
  def setup_method(self, method):
    self.driver = webdriver.Firefox()
    self.vars = {}
    try:
      self.driver.get("http://localhost:8081/")
      self.driver.execute_script("window.localStorage.clear(); window.sessionStorage.clear();")
    except Exception:
      pass
  
  def teardown_method(self, method):
    self.driver.quit()

  def safe_click(self, locator, timeout=15):
    wait = WebDriverWait(self.driver, timeout)
    end_time = time.time() + timeout
    while time.time() < end_time:
      try:
        element = wait.until(EC.presence_of_element_located(locator))
        try:
          element.click()
          return element
        except Exception:
          try:
            self.driver.execute_script("var el = arguments[0]; if (el) { (el.closest('[tabindex]') || el.closest('[role=\"button\"]') || el.parentElement || el).click(); }", element)
          except Exception:
            pass
          return element
      except (StaleElementReferenceException, ElementClickInterceptedException, NoSuchElementException):
        time.sleep(0.5)
    raise TimeoutException(f"Failed to click element with locator {locator} within {timeout} seconds.")

  def safe_send_keys(self, locator, keys, timeout=15):
    wait = WebDriverWait(self.driver, timeout)
    end_time = time.time() + timeout
    while time.time() < end_time:
      try:
        element = wait.until(EC.visibility_of_element_located(locator))
        element.click()
        element.send_keys(Keys.CONTROL + "a")
        element.send_keys(Keys.BACKSPACE)
        element.send_keys(keys)
        element.send_keys(Keys.TAB)
        return element
      except (StaleElementReferenceException, ElementClickInterceptedException, NoSuchElementException):
        time.sleep(0.5)
    raise TimeoutException(f"Failed to send keys to element with locator {locator} within {timeout} seconds.")

  def test_signup(self):
    self.driver.get("http://localhost:8081/")
    self.driver.set_window_size(1550, 830)
    time.sleep(2.0)
    
    # 1. Click "Get Started" on Welcome screen (after splash screen finishes)
    self.safe_click((By.XPATH, "//*[contains(text(),'Get Started')]"))
    
    # 2. Click "I'm a Vehicle Owner" on Role Selection screen
    self.safe_click((By.XPATH, "//*[contains(text(),'Vehicle Owner')]"))
    
    # Generate unique email for clean repeated testing runs
    unique_email = f"amal{int(time.time())}@gmail.com"
    
    # 3. Fill out Registration Form
    # Full Name
    self.safe_send_keys((By.XPATH, "//input[@placeholder='John Doe']"), "amal babu")
    
    # Email Address
    self.safe_send_keys((By.XPATH, "//input[@placeholder='name@example.com']"), unique_email)
    
    # Phone Number
    self.safe_send_keys((By.XPATH, "//input[@placeholder='10-digit mobile number']"), "9447089631")
    
    # Password
    self.safe_send_keys((By.XPATH, "//input[@placeholder='At least 8 characters']"), "Amalbabu@1234")
    
    # Confirm Password
    confirm_input = self.safe_send_keys((By.XPATH, "//input[@placeholder='Re-enter your password']"), "Amalbabu@1234")
    
    # Click body to blur input and trigger React Native Web validation & state update
    self.driver.find_element(By.TAG_NAME, "body").click()
    time.sleep(1.0)

    # 4. Click "Create Account" submit button (2nd occurrence on page, after form title)
    self.safe_click((By.XPATH, "(//*[text()='Create Account'])[2]"))

    # If click didn't trigger navigation, retry clicking button via JS or click directly
    time.sleep(1.0)

    # 5. Verify successful registration & navigation to owner dashboard
    wait = WebDriverWait(self.driver, 20)
    dashboard_element = wait.until(
      EC.presence_of_element_located((By.XPATH, "//*[contains(.,'Welcome back') or contains(.,'My Vehicles') or contains(.,'Emergency Roadside Breakdown')]"))
    )
    assert dashboard_element is not None, "Registration failed or owner dashboard did not load."
